/** Board 09 travel plan. Reminders are chosen by the user, never prescribed from a phase estimate. */
public final class TravelActivity extends Activity {
    private String cueParent="",renderedRoute="";private final Map<String,Integer> scrolls=new HashMap<>();
    private TravelCuePlan cues;private String cueBefore="",cueError="",pickerKind="reminder";private android.window.OnBackInvokedCallback backCallback;private TravelPlan draft;private TravelPlans.Repository repository;private String route="",query="",error="",token,job="";private YearMonth month;
    private boolean resumed,permissionSave;private Dialog dialog;private Bundle picker;private TravelClock homeDial,targetDial;private TextView homeTime,targetTime,homeDate,targetDate,homeOffset,targetOffset,difference,departureDifference,problem;private LinearLayout body;
    private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable tick=new Runnable(){public void run(){clocks();handler.postDelayed(this,15000);}};private final Runnable poll=this::observe;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);repository=TravelPlans.repository(this);try{draft=repository.load(TravelReminders.clock.getAsLong());cues=new TravelCueStore(repository.prefs).load(draft,TravelReminders.clock.getAsLong());if(state!=null){cueParent=state.getString("cueParent","");Bundle positions=state.getBundle("routeScrolls");if(positions!=null)for(String key:positions.keySet())scrolls.put(key,positions.getInt(key));draft.home=state.getString("home",draft.home);draft.destination=state.getString("destination",draft.destination);draft.departure=LocalDate.parse(state.getString("departure",draft.departure.toString()));draft.minute=state.getInt("minute",draft.minute);draft.days=state.getInt("days",draft.days);draft.reminders=state.getBoolean("reminders",draft.reminders);draft.revision=state.getLong("revision",draft.revision);route=state.getString("route","");query=state.getString("query","");error=state.getString("error","");token=state.getString("token");job=state.getString("job","");picker=state.getBundle("picker");pickerKind=state.getString("pickerKind","reminder");permissionSave=state.getBoolean("permissionSave");cueBefore=state.getString("cueBefore","");cueError=state.getString("cueError","");if(state.containsKey("cues"))cues=TravelCueJson.decode(new org.json.JSONObject(state.getString("cues")));}if(Build.VERSION.SDK_INT>=33){backCallback=this::back;getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,backCallback);}month=state==null?YearMonth.from(draft.departure):YearMonth.parse(state.getString("month",YearMonth.from(draft.departure).toString()));render();if(state==null&&draft.revision>0){job="reconcile";token=UUID.randomUUID().toString();render();}}catch(Exception failure){unavailable(failure);}}
    @Override protected void onResume(){super.onResume();resumed=true;handler.post(tick);observe();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(tick);handler.removeCallbacks(poll);super.onPause();}
    private void unavailable(Exception failure){draft=null;token=null;body=Design.page(this,false,null,n->{});RecordUi.header(body,"Travel mode",this::finish);Design.text(body,failure.getMessage()==null?"Your travel plan could not be read.":failure.getMessage(),15,400,Design.MUTED);Design.button(body,"Try again",true,this::recreate);}
    private void render(){
        rememberScroll();homeDial=targetDial=null;problem=null;
        switch(route){
            case "date":case "cue-date":calendar();break;
            case "cues":cueSettings();break;
            case "light":lightSettings();break;
            case "planning":planningSettings();break;
            case "reminders":reminderSettings();break;
            case "home":case "destination":zones();break;
            default:route="";mainPage();
        }
        renderedRoute=route;
        if(body.getParent() instanceof ScrollView scroll){int position=scrolls.getOrDefault(route,0);scroll.post(()->scroll.scrollTo(0,position));}
        clocks();restorePicker();
    }
    private void rememberScroll(){if(body!=null&&body.getParent() instanceof ScrollView scroll)scrolls.put(renderedRoute,scroll.getScrollY());}
    private void go(String destination){route=destination;render();}
    private void mainPage(){
        body=Design.page(this,false,null,n->{});RecordUi.header(body,"Travel mode",this::back);Design.space(body,10);
        Design.text(body,"Target time zone",15,600,Design.INK);Design.space(body,6);
        zoneCard("clock",draft.destination,"Target time zone",()->zoneRoute("destination"));Design.space(body,6);
        zoneCard("home",draft.home,"Home time zone",()->zoneRoute("home"));Design.space(body,8);Design.line(body);
        PlanActivity.detail(body,"calendar","Departure date",null,draft.departure.format(DateTimeFormatter.ofPattern("d MMM uuuu",Locale.getDefault())),()->{month=YearMonth.from(draft.departure);go("date");});
        Design.line(body);Design.space(body,12);Design.text(body,"Time difference · now",14,600,Design.INK);Design.space(body,6);
        clockRow();Design.space(body,8);Design.line(body);Design.space(body,12);
        Design.toggle(body,"Experimental light cues","Flashlight windows · manual arming required",cues.enabled,on->{if(on)openCues();else{cues=cues.change(false,cues.reviewed,cues.first,cues.minute,cues.minutes,cues.nights);render();}});
        PlanActivity.detail(body,"flashlight","Light source","Window, manual arming and limits","Phone flashlight",()->go("light"));Design.line(body);
        PlanActivity.detail(body,"calendar","Schedules & reminders",draft.reminders?"Daylight at "+Design.clock(this,draft.minute)+" · "+draft.days+(draft.days==1?" day":" days"):"Daylight reminders off · pre-travel sleep shifts",null,()->go("planning"));
        footer(true);
    }
    private void detailPage(String title){body=Design.page(this,false,null,n->{});RecordUi.header(body,title,this::back);Design.text(body,route.equals("reminders")?"Travel mode · Schedules & reminders":"Travel mode",12,400,Design.MUTED);Design.space(body,14);}
    private void planningSettings(){
        detailPage("Schedules & reminders");
        PlanActivity.detail(body,"sun","Daylight reminders","Destination time · "+TravelPlan.city(draft.destination),draft.reminders?Design.clock(this,draft.minute)+" · "+draft.days+(draft.days==1?" day":" days"):"Off",()->go("reminders"));Design.line(body);
        PlanActivity.detail(body,"bed","Pre-travel sleep schedule","Bedtime shifts and wake-up alarm drafts",null,this::sleepSchedule);Design.line(body);
        Design.space(body,12);Design.text(body,"Save your trip before opening a dated sleep schedule. Its reminder and alarm choices are reviewed separately.",13,400,Design.MUTED);
        footer(false);
    }
    private void reminderSettings(){
        detailPage("Daylight reminders");
        Design.toggle(body,"Daylight reminders","Destination time · Android may delay reminders",draft.reminders,on->{draft.reminders=on;render();});Design.space(body,8);
        PlanActivity.detail(body,"clock","Reminder time",draft.destination,Design.clock(this,draft.minute),this::pickTime);Design.line(body);
        PlanActivity.detail(body,"calendar","Remind for","From departure date in destination time",draft.days+(draft.days==1?" day":" days"),this::pickDays);Design.line(body);
        TravelReminders.Request pending=repository.pending();
        if(pending!=null){
            Design.space(body,14);Design.text(body,"Next saved reminder",14,600,Design.INK);Design.space(body,6);
            try{TravelPlan saved=repository.load(TravelReminders.clock.getAsLong());
                if(pending.revision!=saved.revision)throw new IllegalStateException();
                ZoneId zone=ZoneId.of(saved.destination);
                Design.text(body,RecordUi.date(pending.at,zone)+" · "+RecordUi.clock(this,pending.at,zone)+"\n"+saved.destination,13,400,Design.MUTED);
            }catch(RuntimeException unavailable){Design.text(body,"Saved reminder needs reconciliation.",13,400,Design.MUTED);}
        }else if(draft.reminders&&draft.revision>0&&draft.next(TravelReminders.clock.getAsLong(),repository.delivered())==0){Design.space(body,12);Design.text(body,"This draft’s reminder period has ended.",13,400,Design.MUTED);}
        Design.space(body,14);Design.text(body,"Changes stay in your trip draft until Save travel settings.",13,400,Design.MUTED);
        footer(false);
    }
    private void lightSettings(){
        detailPage("Light-cue settings");
        PlanActivity.detail(body,"flashlight","Light source",null,"Phone flashlight",null);Design.line(body);
        PlanActivity.detail(body,"calendar","Cue window",cues.home,cues.enabled?cueSummary():"Not enabled",this::openCues);Design.line(body);
        PlanActivity.detail(body,"moon","During manual tracking","Arm from a current recording; never starts automatically",null,null);Design.line(body);
        if(cues.enabled)Design.button(body,"Review & arm cues",false,this::reviewCues);
        PlanActivity.detail(body,"info","About experimental cues","Requested pulses and device limits",null,this::aboutCues);
        footer(false);
    }
    private void aboutCues(){pickerKind="about";open(()->SleepPicker.message(this,"Experimental light cues","Your chosen window requests a brief flashlight pulse every 15 seconds. Android and your flashlight may stretch or miss requests. This is not a measured light dose or a proven jet-lag treatment. Saving settings never starts light output."));}
    private void reviewCues(){try{TravelCuePlan saved=new TravelCueStore(repository.prefs).load(repository.load(TravelReminders.clock.getAsLong()),TravelReminders.clock.getAsLong());if(!saved.enabled||!sameSaved(saved))throw new IllegalStateException("Save your travel settings before arming cues.");startActivity(RecordUi.intent(this,TravelCueReviewActivity.class));}catch(Exception failure){show(failure.getMessage());}}
    private void footer(boolean save){
        LinearLayout footer=Design.col(this);footer.setPadding(Design.dp(this,24),0,Design.dp(this,24),Design.dp(this,12));
        ((LinearLayout)body.getParent().getParent()).addView(footer,new LinearLayout.LayoutParams(-1,-2));
        String issue=error.isEmpty()&&!repository.error().isEmpty()?"Reminders need attention: "+repository.error():error;
        problem=Design.text(footer,issue,12,500,0xffa93919);problem.setContentDescription("Travel settings error");problem.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);problem.setVisibility(issue.isEmpty()?View.GONE:View.VISIBLE);
        if(!repository.error().isEmpty())Design.button(footer,"Retry saved reminders",false,()->startJob("reconcile"));
        if(draft.reminders&&!TravelReminders.port.allowed(this))Design.button(footer,"Allow reminder notifications",false,this::notifications);
        Design.button(footer,token!=null?"Saving…":save?"Save travel settings":"Done",true,save?this::save:this::back);
        if(token!=null){RecordUi.enabled(body,false);RecordUi.enabled(footer,false);}
    }
    private void sleepSchedule(){try{TravelPlan saved=repository.load(TravelReminders.clock.getAsLong());if(saved.revision<=0||saved.revision!=draft.revision||!saved.home.equals(draft.home)||!saved.destination.equals(draft.destination)||!saved.departure.equals(draft.departure))throw new IllegalStateException("Save your trip before reviewing a pre-travel sleep schedule.");startActivity(RecordUi.intent(this,TripSleepActivity.class));}catch(Exception invalid){show(invalid.getMessage());}}
    private void changedTrip(){cues=new TravelCuePlan(cues.revision,draft.revision,false,false,draft.home,draft.destination,cues.first,cues.minute,cues.minutes,cues.nights);}
    private boolean sameSaved(TravelCuePlan saved){return saved.revision==cues.revision&&saved.tripRevision==draft.revision&&saved.home.equals(draft.home)&&saved.destination.equals(draft.destination)&&saved.first.equals(cues.first)&&saved.minute==cues.minute&&saved.minutes==cues.minutes&&saved.nights==cues.nights&&saved.enabled==cues.enabled;}
    private String cueSummary(){return cues.first.format(DateTimeFormatter.ofPattern("d MMM",Locale.getDefault()))+" · "+Design.clock(this,cues.minute);}
    private void openCues(){cueParent=route.equals("light")?"light":"";cueError="";cueBefore=TravelCueJson.encode(cues).toString();route="cues";render();}
    private void cueSettings(){body=Design.page(this,false,null,n->{});RecordUi.header(body,"Light-cue window",this::back);Design.text(body,cueParent.equals("light")?"Travel mode · Light-cue settings":"Travel mode",12,400,Design.MUTED);Design.space(body,12);Design.text(body,"Choose your window",22,600,Design.INK);Design.space(body,6);Design.text(body,"Home time · "+cues.home,13,400,Design.MUTED);Design.space(body,18);
        PlanActivity.detail(body,"calendar","First night",null,cues.first.format(DateTimeFormatter.ofPattern("d MMM uuuu",Locale.getDefault())),()->{month=YearMonth.from(cues.first);route="cue-date";render();});Design.line(body);
        PlanActivity.detail(body,"clock","Start time",null,Design.clock(this,cues.minute),this::pickCueTime);Design.line(body);
        PlanActivity.detail(body,"clock","Window length",null,cues.minutes+" min",this::pickCueLength);Design.line(body);
        PlanActivity.detail(body,"calendar","Cue nights","Before departure",cues.nights+(cues.nights==1?" night":" nights"),this::pickCueNights);Design.line(body);Design.space(body,18);
        Design.text(body,"Requested pulse: 2 ms every 15 seconds",14,600,Design.INK);Design.space(body,7);Design.text(body,"Actual light timing and intensity are not measured. Times are yours to choose, not a treatment recommendation.",13,400,Design.MUTED);Design.space(body,16);Design.text(body,"Only a current manual recording can be armed. Pause, stop, alarm, clock changes or output errors stop the cues. Missed pulses are skipped.",13,400,Design.MUTED);
        LinearLayout footer=RecordUi.footer(body);TextView issue=Design.text(footer,cueError,12,500,0xffa93919);issue.setContentDescription("Light-cue window error");issue.setVisibility(cueError.isEmpty()?View.GONE:View.VISIBLE);Design.button(footer,"Use experimental cues",true,()->{try{TravelCuePlan reviewed=cues.change(true,true,cues.first,cues.minute,cues.minutes,cues.nights);reviewed.validateTrip(draft);if(reviewed.next(TravelReminders.clock.getAsLong())==null)throw new IllegalArgumentException("Choose a window that has not ended.");cues=reviewed;cueBefore="";cueError="";route=cueParent;render();}catch(Exception failure){cueError=failure.getMessage();issue.setText(cueError);issue.setVisibility(View.VISIBLE);}});Design.button(footer,"Cancel",false,this::back);
    }
    private void zoneCard(String icon,String zone,String title,Runnable choose){LinearLayout row=Design.row(this);Design.pad(row,12,8);row.setMinimumHeight(Design.dp(this,72));row.setBackground(Design.outline(this,Color.TRANSPARENT,Design.LINE,16));Design.Icon glyph=new Design.Icon(this,icon,Design.BROWN);glyph.setPadding(Design.dp(this,10),Design.dp(this,10),Design.dp(this,10),Design.dp(this,10));glyph.setBackground(Design.shape(this,Design.SOFT,30));row.addView(glyph,new LinearLayout.LayoutParams(Design.dp(this,50),Design.dp(this,50)));LinearLayout copy=Design.col(this);copy.setPadding(Design.dp(this,14),0,0,0);Design.text(copy,title.equals("Target time zone")?TravelPlan.city(zone):title,16,600,Design.INK);Design.space(copy,4);Design.text(copy,title.equals("Home time zone")?TravelPlan.city(zone)+" · "+zone:zone,12,400,Design.MUTED);Design.space(copy,3);TextView offset=Design.text(copy,TravelPlan.offset(zone,TravelReminders.clock.getAsLong()),11,400,Design.MUTED);if(title.equals("Target time zone"))targetOffset=offset;else homeOffset=offset;row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));row.addView(new Design.Icon(this,"chevron",Design.BROWN),new LinearLayout.LayoutParams(Design.dp(this,20),Design.dp(this,20)));row.setContentDescription(title);row.setFocusable(true);row.setOnClickListener(v->{InteractionFeedback.action(v);choose.run();});body.addView(row);}
    private void clockRow(){LinearLayout row=Design.row(this);LinearLayout left=clockColumn(row,draft.home,true),middle=Design.col(this),right;middle.setGravity(Gravity.CENTER);Design.text(middle,"→",24,400,Design.BROWN).setGravity(Gravity.CENTER);difference=Design.text(middle,"",15,600,Design.INK);difference.setGravity(Gravity.CENTER);row.addView(middle,new LinearLayout.LayoutParams(0,-2,1));right=clockColumn(row,draft.destination,false);body.addView(row);departureDifference=Design.text(body,"",11,400,Design.MUTED);departureDifference.setGravity(Gravity.CENTER);}
    private LinearLayout clockColumn(LinearLayout row,String zone,boolean home){LinearLayout col=Design.col(this);col.setGravity(Gravity.CENTER);Design.text(col,TravelPlan.city(zone),12,500,Design.INK).setGravity(Gravity.CENTER);TravelClock dial=new TravelClock(this,zone,home?0xffffe4aa:0xffdfd2ff);col.addView(dial,new LinearLayout.LayoutParams(Design.dp(this,72),Design.dp(this,72)));TextView clock=Design.text(col,"",14,600,Design.INK);clock.setGravity(Gravity.CENTER);TextView date=Design.text(col,"",10,400,Design.MUTED);date.setGravity(Gravity.CENTER);row.addView(col,new LinearLayout.LayoutParams(0,-2,1));if(home){homeDial=dial;homeTime=clock;homeDate=date;}else{targetDial=dial;targetTime=clock;targetDate=date;}return col;}
    private void clocks(){if(homeDial==null||targetDial==null||draft==null||!route.isEmpty())return;long now=TravelReminders.clock.getAsLong();homeDial.update(now);targetDial.update(now);DateTimeFormatter dateFormat=DateTimeFormatter.ofPattern("EEE d MMM",Locale.getDefault());homeDate.setText(Instant.ofEpochMilli(now).atZone(ZoneId.of(draft.home)).format(dateFormat));targetDate.setText(Instant.ofEpochMilli(now).atZone(ZoneId.of(draft.destination)).format(dateFormat));homeOffset.setText(TravelPlan.offset(draft.home,now));targetOffset.setText(TravelPlan.offset(draft.destination,now));homeTime.setText(RecordUi.clock(this,now,ZoneId.of(draft.home)));targetTime.setText(RecordUi.clock(this,now,ZoneId.of(draft.destination)));difference.setText(TravelPlan.difference(draft.differenceSeconds(now)));departureDifference.setText("On departure day: "+TravelPlan.difference(draft.differenceSeconds(draft.departureAnchor())));homeTime.setContentDescription("Home clock "+RecordUi.date(now,ZoneId.of(draft.home))+" "+homeTime.getText());targetTime.setContentDescription("Destination clock "+RecordUi.date(now,ZoneId.of(draft.destination))+" "+targetTime.getText());}
    private void zoneRoute(String route){this.route=route;query="";render();}
    private void zones(){body=Design.page(this,false,null,n->{});RecordUi.header(body,route.equals("home")?"Home time zone":"Target time zone",this::back);EditText search=new EditText(this);search.setSingleLine(true);search.setTextSize(16*Appearance.scale(this));search.setTypeface(Design.font(this,400));search.setTextColor(Design.INK);search.setHint("Search city or IANA zone");search.setContentDescription("Search time zones");Design.pad(search,14,12);search.setBackground(Design.shape(this,Design.SOFT,14));body.addView(search,new LinearLayout.LayoutParams(-1,-2));Design.space(body,8);LinearLayout results=Design.col(this);body.addView(results);search.setText(query);fillZones(results);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();fillZones(results);}public void afterTextChanged(Editable e){}});}
    private void fillZones(LinearLayout results){results.removeAllViews();List<String> matches=TravelPlan.zones(query);if(matches.isEmpty()){Design.text(results,"No matching time zone.",15,400,Design.MUTED);return;}for(String zone:matches.subList(0,Math.min(60,matches.size()))){boolean selected=zone.equals(route.equals("home")?draft.home:draft.destination);LinearLayout row=Design.row(this);Design.pad(row,8,14);row.setMinimumHeight(Design.dp(this,60));row.setBackground(Design.touch(this,selected?Design.SOFT:Color.TRANSPARENT,12));row.addView(new SleepPicker.Mark(this,selected),new LinearLayout.LayoutParams(Design.dp(this,24),Design.dp(this,24)));LinearLayout copy=Design.col(this);copy.setPadding(Design.dp(this,12),0,0,0);Design.text(copy,zone,14,selected?600:400,Design.INK);Design.space(copy,4);Design.text(copy,TravelPlan.offset(zone,TravelReminders.clock.getAsLong()),11,400,Design.MUTED);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));SleepPicker.radio(row,selected);row.setContentDescription("Use time zone "+zone);row.setOnClickListener(v->{if(route.equals("home"))draft.home=zone;else draft.destination=zone;changedTrip();route="";render();});results.addView(row);}if(matches.size()>60)Design.text(results,"Search to narrow the list.",12,400,Design.MUTED);}
    private void calendar(){body=Design.page(this,false,null,n->{});RecordUi.header(body,route.equals("cue-date")?"First cue night":"Departure date",this::back);Design.space(body,12);LinearLayout controls=Design.row(this);View previous=Design.iconButton(this,"back","Previous month",()->{month=month.minusMonths(1);render();}),next=Design.iconButton(this,"chevron","Next month",()->{month=month.plusMonths(1);render();});previous.setEnabled(month.isAfter(YearMonth.of(2000,1)));next.setEnabled(month.isBefore(YearMonth.of(2100,12)));controls.addView(previous,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));TextView title=Design.text(this,month.format(DateTimeFormatter.ofPattern("MMMM uuuu",Locale.getDefault())),20,600,Design.INK);title.setGravity(Gravity.CENTER);controls.addView(title,new LinearLayout.LayoutParams(0,-2,1));controls.addView(next,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(controls);Design.space(body,10);String[] weekdays={"M","T","W","T","F","S","S"};LinearLayout labels=Design.row(this);for(String label:weekdays){TextView value=Design.text(this,label,12,500,Design.MUTED);value.setGravity(Gravity.CENTER);labels.addView(value,new LinearLayout.LayoutParams(0,Design.dp(this,40),1));}body.addView(labels);int offset=month.atDay(1).getDayOfWeek().getValue()-1;for(int week=0;week<(offset+month.lengthOfMonth()+6)/7;week++){LinearLayout row=Design.row(this);for(int col=0;col<7;col++){int day=week*7+col-offset+1;if(day<1||day>month.lengthOfMonth()){row.addView(new View(this),new LinearLayout.LayoutParams(0,Design.dp(this,48),1));continue;}LocalDate date=month.atDay(day);TextView value=Design.text(this,""+day,16,500,date.equals(route.equals("cue-date")?cues.first:draft.departure)?Design.CREAM:Design.INK);value.setGravity(Gravity.CENTER);value.setBackground(Design.touch(this,date.equals(route.equals("cue-date")?cues.first:draft.departure)?Design.BROWN:Color.TRANSPARENT,24));value.setContentDescription((route.equals("cue-date")?"Cue date ":"Departure ")+date);value.setSelected(date.equals(route.equals("cue-date")?cues.first:draft.departure));value.setFocusable(true);value.setOnClickListener(v->{if(route.equals("cue-date")){cues=cues.change(false,false,date,cues.minute,cues.minutes,cues.nights);route="cues";}else{draft.departure=date;changedTrip();route="";}render();});row.addView(value,new LinearLayout.LayoutParams(0,Design.dp(this,48),1));}body.addView(row);}Design.space(body,16);Design.text(body,route.equals("cue-date")?"Cue windows use your saved home time zone.":"Reminders begin on this date in the destination time zone.",13,400,Design.MUTED);}
    private void restorePicker(){if(picker==null)return;Bundle restore=picker;picker=null;switch(pickerKind){case "about":aboutCues();break;case "cueTime":pickCueTime();break;case "cueLength":pickCueLength();break;case "cueNights":pickCueNights();break;case "reminderDays":pickDays();break;default:pickTime();}if(dialog!=null)dialog.onRestoreInstanceState(restore);}
    private void pickCueTime(){pickerKind="cueTime";open(()->SleepPicker.time(this,"Cue window start",cues.minute,n->{cues=cues.change(false,false,cues.first,n,cues.minutes,cues.nights);render();}));}
    private void pickCueLength(){pickerKind="cueLength";open(()->SleepPicker.choices(this,"Cue window length",new String[]{"15 min","30 min","60 min"},cues.minutes==15?0:cues.minutes==30?1:2,n->{cues=cues.change(false,false,cues.first,cues.minute,new int[]{15,30,60}[n],cues.nights);render();}));}
    private void pickCueNights(){pickerKind="cueNights";String[] labels=new String[14];for(int n=0;n<14;n++)labels[n]=(n+1)+(n==0?" night":" nights");open(()->SleepPicker.choices(this,"Cue nights",labels,cues.nights-1,n->{cues=cues.change(false,false,cues.first,cues.minute,cues.minutes,n+1);render();}));}
    private void pickTime(){pickerKind="reminder";open(()->SleepPicker.time(this,"Daylight reminder time",draft.minute,value->{draft.minute=value;render();}));}
    private void pickDays(){pickerKind="reminderDays";String[] labels=new String[14];for(int n=0;n<14;n++)labels[n]=(n+1)+(n==0?" day":" days");open(()->SleepPicker.choices(this,"Reminder days",labels,draft.days-1,n->{draft.days=n+1;render();}));}
    private void open(java.util.function.Supplier<Dialog> create){if(dialog!=null&&dialog.isShowing())return;dialog=create.get();}
    private void save(){if(token!=null)return;try{draft.validate();cues.validateTrip(draft);if(cues.enabled&&cues.next(TravelReminders.clock.getAsLong())==null)throw new IllegalArgumentException("These cue windows ended. Review another window or turn cues off.");if(draft.reminders&&draft.next(TravelReminders.clock.getAsLong(),0)==0)throw new IllegalArgumentException("These reminder days have passed. Choose a later date or turn reminders off.");if(draft.reminders&&!TravelReminders.port.allowed(this)){notifications(true);return;}startJob("save");}catch(Exception failure){show(failure.getMessage());}}
    private void notifications(){notifications(false);}
    private void notifications(boolean saveAfter){permissionSave=saveAfter;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED&&(!repository.prefs.getBoolean("travelNotificationAsked",false)||shouldShowRequestPermissionRationale(Manifest.permission.POST_NOTIFICATIONS))){repository.prefs.edit().putBoolean("travelNotificationAsked",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},81);}else{permissionSave=false;show("Allow Travel daylight reminders in Android notification settings.");startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));}}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==81){boolean continueSave=permissionSave;permissionSave=false;if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED){if(continueSave)save();else render();}else show("Notifications were not allowed. Turn reminders off to save a clock-only plan, or allow them in Android app settings.");}}
    private void startJob(String kind){if(token!=null)return;job=kind;token=UUID.randomUUID().toString();error="";render();observe();}
    private void observe(){if(!resumed||token==null||draft==null)return;TravelPlan copy=draft.copy();TravelCuePlan savedCues=cues;TravelPlans.Repository repo=repository;String kind=job;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{if(kind.equals("save")){repo.save(copy,savedCues,TravelReminders.clock.getAsLong());TravelCues.changed();try{TripSleepRuntime.reconcile(app);}catch(RuntimeException unavailable){new TripSleepStore(app).error("Trip saved. Review the travel sleep reminder schedule.");}}try{TravelReminders.apply(app);return null;}catch(Exception failure){return failure.getMessage();}});if(!operation.done){handler.postDelayed(poll,75);return;}PlanOperations.forget(token);token=null;if(operation.error!=null){error=operation.error;render();return;}if(kind.equals("save")){draft=repository.load(TravelReminders.clock.getAsLong());cues=new TravelCueStore(repository.prefs).load(draft,TravelReminders.clock.getAsLong());}if(operation.notice!=null){error="Plan saved. Reminders need attention: "+operation.notice;render();return;}error="";if(kind.equals("save")){setResult(RESULT_OK);finish();}else render();}
    private void show(String value){error=value==null?"Travel settings need attention.":value;if(problem!=null){problem.setText(error);problem.setVisibility(View.VISIBLE);problem.post(()->problem.requestRectangleOnScreen(new android.graphics.Rect(0,0,problem.getWidth(),problem.getHeight()),true));}}
    private void back(){if(token!=null)return;if(route.equals("cue-date")){route="cues";render();}else if(route.equals("cues")){try{if(!cueBefore.isEmpty())cues=TravelCueJson.decode(new org.json.JSONObject(cueBefore));}catch(Exception failure){show("The window could not be restored. Reopen this page.");return;}cueBefore="";route=cueParent;render();}else if(route.equals("reminders")){route="planning";render();}else if(!route.isEmpty()){route="";render();}else finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override public void finish(){if(token==null)super.finish();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft==null)return;rememberScroll();Bundle positions=new Bundle();for(Map.Entry<String,Integer> entry:scrolls.entrySet())positions.putInt(entry.getKey(),entry.getValue());state.putBundle("routeScrolls",positions);state.putString("cueParent",cueParent);state.putString("pickerKind",pickerKind);state.putString("cues",TravelCueJson.encode(cues).toString());state.putString("cueBefore",cueBefore);state.putString("cueError",cueError);state.putString("home",draft.home);state.putString("destination",draft.destination);state.putString("departure",draft.departure.toString());state.putInt("minute",draft.minute);state.putInt("days",draft.days);state.putBoolean("reminders",draft.reminders);state.putLong("revision",draft.revision);state.putString("route",route);state.putString("month",month.toString());state.putString("query",query);state.putString("error",error);state.putString("token",token);state.putString("job",job);state.putBoolean("permissionSave",permissionSave);if(dialog!=null&&dialog.isShowing())state.putBundle("picker",dialog.onSaveInstanceState());}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(dialog!=null)dialog.dismiss();if(Build.VERSION.SDK_INT>=33&&backCallback!=null)getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback(backCallback);super.onDestroy();}
}
